'use client';

import type { PhoneCountry } from '@/components/ui/phone-input';

import { AccountPhoneNumbersView } from './account-phone-numbers-view';
import { useAccountPhoneNumbers, type UseAccountPhoneNumbersOptions } from './use-account-phone-numbers';

export type AccountPhoneNumbersProps = UseAccountPhoneNumbersOptions & {
  /**
   * Identifies the signed-in account the adapter is bound to. Changing it discards all local state and reloads,
   * so a response for one account can never land in another's list.
   */
  identityKey?: string;
  /** Overrides the country detected from the browser's language preferences. */
  defaultCountry?: PhoneCountry;
  className?: string;
};

/**
 * Add a phone number, text it a code, and verify it: the possession proof that turns a claimed number into a
 * sign-in identifier and second factor. Data access stays in the host through `adapter`.
 */
export function AccountPhoneNumbers({ identityKey, ...props }: AccountPhoneNumbersProps) {
  return <AccountPhoneNumbersController key={identityKey} {...props} />;
}

function AccountPhoneNumbersController({
  defaultCountry,
  className,
  ...options
}: Omit<AccountPhoneNumbersProps, 'identityKey'>) {
  return <AccountPhoneNumbersView {...useAccountPhoneNumbers(options)} defaultCountry={defaultCountry} className={className} />;
}

export { AccountPhoneNumbersView, type AccountPhoneNumbersViewProps } from './account-phone-numbers-view';
export {
  useAccountPhoneNumbers,
  type UseAccountPhoneNumbersOptions,
  type UseAccountPhoneNumbersResult
} from './use-account-phone-numbers';
export {
  AccountPhoneNumbersError,
  AccountPhoneNumbersUnavailableError,
  type AccountPhoneNumber,
  type AccountPhoneNumberRef,
  type AccountPhoneNumbersAction,
  type AccountPhoneNumbersAdapter,
  type AccountPhoneNumbersBusy,
  type AccountPhoneNumbersCodeEntry,
  type AccountPhoneNumbersFeedback,
  type AccountPhoneNumbersScope
} from './account-phone-numbers-contracts';
export {
  defaultAccountPhoneNumbersMessages,
  type AccountPhoneNumbersMessageOverrides,
  type AccountPhoneNumbersMessages
} from './messages';

'use client';

import { useCallback, useId, type FormEvent } from 'react';
import {
  CheckIcon,
  CircleAlertIcon,
  CircleDashedIcon,
  Loader2Icon,
  PlusIcon,
  SmartphoneIcon,
  StarIcon,
  Trash2Icon
} from 'lucide-react';

import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { InputOtp } from '@/components/ui/input-otp';
import { CountryFlag, formatPhoneNumber, PhoneInput, type PhoneCountry } from '@/components/ui/phone-input';
import { Skeleton } from '@/components/ui/skeleton';
import { cn } from '@/lib/utils';

import type {
  AccountPhoneNumber,
  AccountPhoneNumbersBusy,
  AccountPhoneNumbersCodeEntry,
  AccountPhoneNumbersFeedback
} from './account-phone-numbers-contracts';
import {
  interpolateAccountPhoneNumbersMessage as interpolate,
  mergeAccountPhoneNumbersMessages,
  type AccountPhoneNumbersMessageOverrides,
  type AccountPhoneNumbersMessages
} from './messages';

export type AccountPhoneNumbersViewProps = {
  /** `null` until the first list load succeeds. */
  phones: readonly AccountPhoneNumber[] | null;
  loading: boolean;
  /** The backend has no phone support: a quiet notice replaces the list. */
  unavailable?: boolean;
  feedback?: AccountPhoneNumbersFeedback;
  /** E.164, or '' when empty. */
  draft: string;
  busy?: AccountPhoneNumbersBusy;
  codeEntry?: AccountPhoneNumbersCodeEntry;
  codeLength?: number;
  defaultCountry?: PhoneCountry;
  messages?: AccountPhoneNumbersMessageOverrides;
  className?: string;
  onDraftChange: (value: string) => void;
  onCodeChange: (code: string) => void;
  onAdd: (event: FormEvent<HTMLFormElement>) => void;
  onSendCode: (phone: AccountPhoneNumber) => void;
  onVerify: (phone: AccountPhoneNumber, event: FormEvent<HTMLFormElement>) => void;
  onCancelCode: () => void;
  onRemove: (phone: AccountPhoneNumber) => void;
  onRetry: () => void;
};

type RowAction = Extract<AccountPhoneNumbersBusy, { scope: 'phone' }>['action'];

const spinner = <Loader2Icon className="animate-spin motion-reduce:animate-none" aria-hidden />;
/**
 * The add field sits on the panel's 16px inset (10px in a narrow panel); its country picker then pads its flag by
 * 1px border + 12px.
 */
const inset = 'px-4 @max-xs/phones:px-2.5';
/**
 * Rows put their flag on the picker flag's column (16 + 1 + 12 = 29px, or 23px narrow) and use the picker's
 * flag→code gap, so each number's calling code lands exactly under the picker's: one optical axis instead of two
 * edges 13px apart.
 */
const rowInset = 'ps-[29px] pe-4 @max-xs/phones:ps-[23px] @max-xs/phones:pe-2.5';
const lead = 'gap-2';
/** Text under a number starts where the number does (18px flag + 8px gap) once the panel is wide enough. */
const indent = '@sm/phones:ps-6.5';
/** Every inline message is one quiet line in the same slot and size as the helper text it replaces. */
const helper = 'text-xs text-pretty';
/** Entrances use @starting-style, so they need no animation library and settle instantly with reduced motion. */
const enter = 'transition-[opacity,translate] duration-200 ease-out starting:opacity-0 motion-reduce:transition-none';
const DIGITS = /^\d+$/;

function StatusRegion({ notice }: { notice?: string }) {
  return notice ? (
    <p role="status" className="sr-only">
      {notice}
    </p>
  ) : null;
}

/** Quiet labels on the number's own line; each leads with its icon, which is also what separates them. */
function PhoneStatus({
  phone,
  justVerified,
  messages
}: {
  phone: AccountPhoneNumber;
  justVerified: boolean;
  messages: AccountPhoneNumbersMessages;
}) {
  return (
    <span
      // Remounts when verification flips, so the new label can fade in once.
      key={phone.isVerified ? 'verified' : 'unverified'}
      className={cn(
        'flex items-center gap-3 text-xs [&_svg]:size-3 [&_svg]:shrink-0 [&_svg]:stroke-[2.5]',
        justVerified && cn(enter, 'duration-300')
      )}
    >
      {phone.isVerified ? (
        <span className="flex items-center gap-1 text-muted-foreground">
          <CheckIcon className="text-success" aria-hidden />
          <span>{messages.verified}</span>
        </span>
      ) : (
        <span className="flex items-center gap-1 text-warning-foreground">
          <CircleDashedIcon aria-hidden />
          <span>{messages.unverified}</span>
        </span>
      )}
      {phone.isPrimary ? (
        <span className="flex items-center gap-1 text-muted-foreground">
          <StarIcon className="fill-current" aria-hidden />
          <span>{messages.primary}</span>
        </span>
      ) : null}
    </span>
  );
}

function CodeEntryForm({
  phone,
  display,
  code,
  codeLength,
  error,
  rowBusy,
  messages,
  onCodeChange,
  onVerify,
  onCancel,
  onResend
}: {
  phone: AccountPhoneNumber;
  display: string;
  code: string;
  codeLength: number;
  error?: string;
  rowBusy?: RowAction;
  messages: AccountPhoneNumbersMessages;
  onCodeChange: (code: string) => void;
  onVerify: (phone: AccountPhoneNumber, event: FormEvent<HTMLFormElement>) => void;
  onCancel: () => void;
  onResend: () => void;
}) {
  const hintId = useId();
  // Stable, so it runs once when the field mounts rather than stealing focus on every keystroke.
  const focusFirstDigit = useCallback((node: HTMLDivElement | null) => node?.querySelector('input')?.focus(), []);
  const complete = code.length === codeLength && DIGITS.test(code);

  return (
    <form className={cn('mt-3 space-y-2.5 starting:-translate-y-1', indent, enter)} onSubmit={(event) => onVerify(phone, event)}>
      <p id={hintId} className={cn(helper, 'tabular-nums text-muted-foreground')}>
        {/* No-break spaces keep the number on one line when the hint wraps. */}
        {interpolate(messages.codeHint, { length: codeLength, number: display.replace(/ /g, '\u00a0') })}
      </p>
      <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
        <InputOtp
          ref={focusFirstDigit}
          size="sm"
          length={codeLength}
          groupEvery={codeLength % 3 === 0 ? 3 : undefined}
          className="max-w-[16rem]"
          value={code}
          onChange={onCodeChange}
          isInvalid={Boolean(error)}
          isDisabled={rowBusy === 'verify'}
          aria-label={messages.codeLabel}
          aria-describedby={hintId}
        />
        <div className="flex items-center gap-1">
          {/* 36px, the height of the code boxes beside them. */}
          <Button type="submit" size="sm" className="h-9" disabled={Boolean(rowBusy) || !complete}>
            {rowBusy === 'verify' ? spinner : null}
            {rowBusy === 'verify' ? messages.verifyingButton : messages.verifyButton}
          </Button>
          <Button size="sm" variant="ghost" className="h-9 text-muted-foreground" disabled={Boolean(rowBusy)} onClick={onCancel}>
            {messages.cancelButton}
          </Button>
        </div>
      </div>
      <p role={error ? 'alert' : undefined} className={cn(helper, error ? 'text-destructive' : 'text-muted-foreground')}>
        {error ?? messages.codeHelp}{' '}
        <button
          type="button"
          className="font-medium text-foreground underline-offset-2 hover:underline disabled:opacity-64"
          disabled={Boolean(rowBusy)}
          onClick={onResend}
        >
          {rowBusy === 'send' ? messages.sendingCodeButton : messages.resendCodeButton}
        </button>
      </p>
    </form>
  );
}

function PhoneRow({
  phone,
  feedback,
  rowBusy,
  code,
  codeLength,
  messages,
  onCodeChange,
  onSendCode,
  onVerify,
  onCancelCode,
  onRemove
}: {
  phone: AccountPhoneNumber;
  feedback?: AccountPhoneNumbersFeedback;
  rowBusy?: RowAction;
  /** Set while this row's code field is open. */
  code?: string;
  codeLength: number;
  messages: AccountPhoneNumbersMessages;
} & Pick<AccountPhoneNumbersViewProps, 'onCodeChange' | 'onSendCode' | 'onVerify' | 'onCancelCode' | 'onRemove'>) {
  const display = formatPhoneNumber(phone.number);
  const codeOpen = !phone.isVerified && code !== undefined;
  const error = feedback?.error;

  return (
    <li className={cn('py-3', rowInset)} data-slot="account-phone-number">
      <div className={cn('flex items-center', lead)}>
        {/* The one thing that differs between rows is where the number is from, so that leads. */}
        <CountryFlag number={phone.number} />
        {/* One line; the labels drop under the number only when the row runs out of room. */}
        <div className="flex min-w-0 flex-1 flex-wrap items-center gap-x-2.5 gap-y-0.5">
          <p className="whitespace-nowrap text-sm font-medium tabular-nums text-foreground">{display}</p>
          <PhoneStatus phone={phone} justVerified={Boolean(feedback?.notice) && phone.isVerified} messages={messages} />
        </div>
        {/* -me pulls the trash glyph onto the row's text edge; its button padding is air. */}
        <div className="-me-1.5 flex shrink-0 items-center gap-1">
          {!phone.isVerified && !codeOpen ? (
            <Button
              size="xs"
              variant="outline"
              // Narrow panels: a compact button so the number, not the action, keeps the room.
              className="@max-xs/phones:h-6 @max-xs/phones:px-2"
              disabled={Boolean(rowBusy)}
              onClick={() => onSendCode(phone)}
            >
              {rowBusy === 'send' ? spinner : null}
              {rowBusy === 'send' ? messages.sendingCodeButton : messages.sendCodeButton}
            </Button>
          ) : null}
          <Button
            size="icon-xs"
            variant="ghost"
            className="text-muted-foreground hover:bg-destructive/8 hover:text-destructive"
            disabled={Boolean(rowBusy)}
            onClick={() => onRemove(phone)}
            aria-label={interpolate(messages.removeLabel, { number: display })}
          >
            {rowBusy === 'remove' ? spinner : <Trash2Icon aria-hidden />}
          </Button>
        </div>
      </div>

      <StatusRegion notice={feedback?.notice} />

      {codeOpen ? (
        <CodeEntryForm
          phone={phone}
          display={display}
          code={code}
          codeLength={codeLength}
          error={error}
          rowBusy={rowBusy}
          messages={messages}
          onCodeChange={onCodeChange}
          onVerify={onVerify}
          onCancel={onCancelCode}
          onResend={() => onSendCode(phone)}
        />
      ) : error ? (
        <p role="alert" className={cn(helper, 'mt-2 text-destructive', indent)}>
          {error}
        </p>
      ) : null}
    </li>
  );
}

function AddPhoneForm({
  draft,
  error,
  adding,
  disabled,
  primary,
  defaultCountry,
  messages,
  onDraftChange,
  onAdd
}: {
  draft: string;
  error?: string;
  adding: boolean;
  disabled: boolean;
  /** The first number is the main action, so its button carries the primary style. */
  primary: boolean;
  defaultCountry?: PhoneCountry;
  messages: AccountPhoneNumbersMessages;
} & Pick<AccountPhoneNumbersViewProps, 'onDraftChange' | 'onAdd'>) {
  const id = useId();
  return (
    <form className={cn('space-y-1.5 bg-muted/40 py-3', inset)} onSubmit={onAdd}>
      <label htmlFor={id} className="sr-only">
        {messages.addLabel}
      </label>
      <div className="flex gap-2">
        <PhoneInput
          id={id}
          className="flex-1"
          placeholder={messages.addPlaceholder}
          autoComplete="tel"
          value={draft}
          onChange={onDraftChange}
          defaultCountry={defaultCountry}
          disabled={adding || disabled}
          invalid={Boolean(error)}
          labels={messages.phoneInput}
          aria-describedby={`${id}-hint`}
        />
        <Button
          type="submit"
          size="sm"
          variant={primary ? 'default' : 'outline'}
          // Stretch to the field's height at every breakpoint instead of a fixed 32px.
          className="h-auto self-stretch @max-xs/phones:px-2"
          disabled={adding || disabled || !draft}
        >
          {adding ? spinner : <PlusIcon aria-hidden />}
          {/* In a narrow panel the number needs the room; the icon carries the action. */}
          <span className="@max-xs/phones:sr-only">{adding ? messages.addingButton : messages.addButton}</span>
        </Button>
      </div>
      <p
        id={`${id}-hint`}
        role={error ? 'alert' : undefined}
        className={cn(helper, error ? 'text-destructive' : 'text-muted-foreground')}
      >
        {error ?? messages.addHint}
      </p>
    </form>
  );
}

function LoadingRows({ label }: { label: string }) {
  return (
    <div role="status" className="divide-y divide-border/60">
      <span className="sr-only">{label}</span>
      {[0, 1].map((row) => (
        <div key={row} className={cn('flex h-13 items-center', lead, rowInset)} aria-hidden>
          <Skeleton className="h-3 w-4.5 rounded-[2px]" />
          <Skeleton className="h-3.5 w-32" />
          <Skeleton className="h-3 w-16" />
        </div>
      ))}
    </div>
  );
}

function EmptyRow({ messages }: { messages: AccountPhoneNumbersMessages }) {
  return (
    <div className={cn('flex items-start py-3.5', lead, rowInset)}>
      {/* The same 18px slot a flag takes, so the first number added lands where this text sits. */}
      <span className="flex h-5 w-4.5 shrink-0 items-center justify-center text-muted-foreground" aria-hidden>
        <SmartphoneIcon className="size-4" />
      </span>
      <div>
        <p className="text-sm font-medium text-foreground">{messages.emptyTitle}</p>
        <p className="text-xs text-muted-foreground">{messages.emptyDescription}</p>
      </div>
    </div>
  );
}

/** Controlled presentation for every state of the phone numbers card; pair it with `useAccountPhoneNumbers`. */
export function AccountPhoneNumbersView({
  phones,
  loading,
  unavailable = false,
  feedback,
  draft,
  busy,
  codeEntry,
  codeLength = 6,
  defaultCountry,
  messages: messageOverrides,
  className,
  onDraftChange,
  onCodeChange,
  onAdd,
  onSendCode,
  onVerify,
  onCancelCode,
  onRemove,
  onRetry
}: AccountPhoneNumbersViewProps) {
  const messages = mergeAccountPhoneNumbersMessages(messageOverrides);
  const cardFeedback = feedback?.scope === 'card' ? feedback : undefined;
  const empty = phones !== null && phones.length === 0;

  return (
    <Card className={cn('gap-5', className)} data-slot="account-phone-numbers">
      <CardHeader className="gap-1">
        <CardTitle className="text-sm font-medium leading-5 tracking-normal">{messages.title}</CardTitle>
        <CardDescription>{messages.description}</CardDescription>
      </CardHeader>

      {/* One measure for everything inside: rows, code entry and the add field share a width, so each action stays
          a short reach from its number on any screen. 36rem fits the widest row (the code entry, ~31rem) with room
          for longer labels; box-content keeps the card's own padding outside it. */}
      <CardContent className="box-content max-w-xl space-y-3">
        {cardFeedback?.error ? (
          <Alert variant="destructive">
            <CircleAlertIcon aria-hidden />
            {/* The alert pins its icon to the first text line, so the row is top-aligned rather than centred on the
                28px button; -3px margins centre the button on that 22.75px line without making the row taller. */}
            <AlertDescription className="flex flex-wrap items-start justify-between gap-x-4 gap-y-2">
              <span>{cardFeedback.error}</span>
              {phones === null ? (
                <Button size="xs" variant="outline" className="-my-[3px]" onClick={onRetry} disabled={loading}>
                  {loading ? spinner : null}
                  {messages.retryButton}
                </Button>
              ) : null}
            </AlertDescription>
          </Alert>
        ) : null}
        <StatusRegion notice={cardFeedback?.notice} />

        {unavailable ? (
          <Alert>
            <CircleAlertIcon aria-hidden />
            <AlertDescription>{messages.unavailable}</AlertDescription>
          </Alert>
        ) : (
          // One surface: the numbers you have, then the way to add another. Its 8px radius sits inside the card's
          // 10px; overflow clips the footer tint to the corners.
          <div className="@container/phones divide-y divide-border/60 overflow-hidden rounded-md border border-border/70 bg-card">
            {phones === null && loading ? <LoadingRows label={messages.loadingLabel} /> : null}
            {empty ? <EmptyRow messages={messages} /> : null}
            {phones && phones.length > 0 ? (
              <ul aria-busy={loading || undefined} className="divide-y divide-border/60">
                {phones.map((phone) => (
                  <PhoneRow
                    key={phone.id}
                    phone={phone}
                    feedback={feedback?.scope === 'phone' && feedback.phoneId === phone.id ? feedback : undefined}
                    rowBusy={busy?.scope === 'phone' && busy.phoneId === phone.id ? busy.action : undefined}
                    code={codeEntry?.phoneId === phone.id ? codeEntry.code : undefined}
                    codeLength={codeLength}
                    messages={messages}
                    onCodeChange={onCodeChange}
                    onSendCode={onSendCode}
                    onVerify={onVerify}
                    onCancelCode={onCancelCode}
                    onRemove={onRemove}
                  />
                ))}
              </ul>
            ) : null}
            <AddPhoneForm
              draft={draft}
              error={feedback?.scope === 'add' ? feedback.error : undefined}
              adding={busy?.scope === 'add'}
              disabled={loading}
              primary={empty}
              defaultCountry={defaultCountry}
              messages={messages}
              onDraftChange={onDraftChange}
              onAdd={onAdd}
            />
          </div>
        )}
      </CardContent>
    </Card>
  );
}

'use client';

import { useEffect, useState, type FormEvent } from 'react';

import { formatPhoneNumber, normalizePhoneNumber } from '@/components/ui/phone-input';

import {
  AccountPhoneNumbersUnavailableError,
  type AccountPhoneNumber,
  type AccountPhoneNumbersAction,
  type AccountPhoneNumbersAdapter,
  type AccountPhoneNumbersBusy,
  type AccountPhoneNumbersCodeEntry,
  type AccountPhoneNumbersFeedback,
  type AccountPhoneNumbersScope
} from './account-phone-numbers-contracts';
import {
  interpolateAccountPhoneNumbersMessage as interpolate,
  mergeAccountPhoneNumbersMessages,
  type AccountPhoneNumbersMessageOverrides,
  type AccountPhoneNumbersMessages
} from './messages';
import type { AccountPhoneNumbersViewProps } from './account-phone-numbers-view';

export type UseAccountPhoneNumbersOptions = {
  /** Loaded from once per mount. Remount (for example with a `key`) when the signed-in identity changes. */
  adapter: AccountPhoneNumbersAdapter;
  messages?: AccountPhoneNumbersMessageOverrides;
  /** Digits in the texted code. */
  codeLength?: number;
  /** Returns the message to show for an error, or undefined to fall back to `messages.errors`. */
  formatError?: (error: unknown, action: AccountPhoneNumbersAction) => string | undefined;
  onError?: (error: unknown, action: AccountPhoneNumbersAction) => void;
};

/** Everything `AccountPhoneNumbersView` needs, including the message overrides, so `{...state}` is enough. */
export type UseAccountPhoneNumbersResult = Omit<AccountPhoneNumbersViewProps, 'className' | 'defaultCountry'>;

function errorCode(error: unknown): string | undefined {
  if (!error || typeof error !== 'object') return undefined;
  const { code, extensions } = error as { code?: unknown; extensions?: { code?: unknown } };
  if (typeof code === 'string') return code;
  return typeof extensions?.code === 'string' ? extensions.code : undefined;
}

function errorMessage(error: unknown, messages: AccountPhoneNumbersMessages) {
  const code = errorCode(error);
  if (code && messages.errors[code]) return messages.errors[code];
  return error instanceof Error && error.message ? error.message : messages.errors.UNKNOWN_ERROR;
}

function scopeOf(busy: AccountPhoneNumbersBusy): AccountPhoneNumbersScope {
  return busy.scope === 'add' ? busy : { scope: 'phone', phoneId: busy.phoneId };
}

/**
 * The add → text a code → verify → remove flow as state for `AccountPhoneNumbersView`. Adding a number texts it a
 * code straight away, a code that no longer applies reloads the list, and every outcome is scoped to the row (or
 * the add form) that caused it.
 */
export function useAccountPhoneNumbers({
  adapter,
  messages: messageOverrides,
  codeLength = 6,
  formatError,
  onError
}: UseAccountPhoneNumbersOptions): UseAccountPhoneNumbersResult {
  const messages = mergeAccountPhoneNumbersMessages(messageOverrides);
  const [phones, setPhones] = useState<readonly AccountPhoneNumber[] | null>(null);
  const [loading, setLoading] = useState(true);
  const [unavailable, setUnavailable] = useState(false);
  const [feedback, setFeedback] = useState<AccountPhoneNumbersFeedback>();
  const [draft, setDraft] = useState('');
  const [busy, setBusy] = useState<AccountPhoneNumbersBusy>();
  const [codeEntry, setCodeEntry] = useState<AccountPhoneNumbersCodeEntry>();

  function fail(cause: unknown, action: AccountPhoneNumbersAction, scope: AccountPhoneNumbersScope) {
    onError?.(cause, action);
    setFeedback({ ...scope, error: formatError?.(cause, action) || errorMessage(cause, messages) });
  }

  async function refresh() {
    setLoading(true);
    setFeedback(undefined);
    try {
      setPhones(await adapter.list());
      setUnavailable(false);
    } catch (cause) {
      if (cause instanceof AccountPhoneNumbersUnavailableError) setUnavailable(true);
      else fail(cause, 'load', { scope: 'card' });
    } finally {
      setLoading(false);
    }
  }

  // Once per mount, matching the adapter contract; a new identity remounts the block.
  useEffect(() => {
    void refresh();
  }, []);

  /** Marks `next` busy, clears old feedback, and shows any failure in the place `next` names. */
  async function run<T>(
    next: AccountPhoneNumbersBusy,
    action: AccountPhoneNumbersAction,
    work: () => Promise<T>
  ): Promise<{ ok: true; value: T } | { ok: false }> {
    setBusy(next);
    setFeedback(undefined);
    try {
      return { ok: true, value: await work() };
    } catch (cause) {
      fail(cause, action, scopeOf(next));
      return { ok: false };
    } finally {
      setBusy(undefined);
    }
  }

  async function sendCode(phone: AccountPhoneNumber) {
    const ref = { id: phone.id, number: phone.number };
    const sent = await run({ scope: 'phone', phoneId: phone.id, action: 'send' }, 'send', () => adapter.sendCode(ref));
    if (!sent.ok) return;
    // Nothing was sent because the number is already verified; reload so the row shows that.
    if (!sent.value) return refresh();
    setCodeEntry({ phoneId: phone.id, code: '' });
    setFeedback({
      scope: 'phone',
      phoneId: phone.id,
      notice: interpolate(messages.codeSentNotice, { number: formatPhoneNumber(phone.number) })
    });
  }

  async function onAdd(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const number = normalizePhoneNumber(draft);
    if (!number) {
      setFeedback({ scope: 'add', error: messages.invalidNumber });
      return;
    }
    const added = await run({ scope: 'add' }, 'add', () => adapter.add({ number }));
    if (!added.ok) return;
    const phone = added.value;
    setPhones((current) => [...(current ?? []), phone]);
    setDraft('');
    if (!phone.isVerified) await sendCode(phone);
  }

  async function onVerify(phone: AccountPhoneNumber, event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const code = codeEntry?.code ?? '';
    if (code.length !== codeLength || !/^\d+$/.test(code)) return;
    const busyRow = { scope: 'phone', phoneId: phone.id, action: 'verify' } as const;
    const verified = await run(busyRow, 'verify', () => adapter.verify({ id: phone.id, number: phone.number, code }));
    if (!verified.ok) return;
    if (!verified.value) {
      setFeedback({ scope: 'phone', phoneId: phone.id, error: messages.wrongCode });
      return;
    }
    setPhones((current) => current?.map((row) => (row.id === phone.id ? { ...row, isVerified: true } : row)) ?? null);
    setCodeEntry(undefined);
    setFeedback({
      scope: 'phone',
      phoneId: phone.id,
      notice: interpolate(messages.verifiedNotice, { number: formatPhoneNumber(phone.number) })
    });
  }

  async function onRemove(phone: AccountPhoneNumber) {
    const busyRow = { scope: 'phone', phoneId: phone.id, action: 'remove' } as const;
    const removed = await run(busyRow, 'remove', () => adapter.remove({ id: phone.id, number: phone.number }));
    if (!removed.ok) return;
    setPhones((current) => current?.filter((row) => row.id !== phone.id) ?? null);
    setCodeEntry((entry) => (entry?.phoneId === phone.id ? undefined : entry));
  }

  return {
    phones,
    loading,
    unavailable,
    feedback,
    draft,
    busy,
    codeEntry,
    codeLength,
    messages: messageOverrides,
    onDraftChange: setDraft,
    onCodeChange: (code) => setCodeEntry((entry) => entry && { ...entry, code }),
    onAdd: (event) => void onAdd(event),
    onSendCode: (phone) => void sendCode(phone),
    onVerify: (phone, event) => void onVerify(phone, event),
    onCancelCode: () => {
      setCodeEntry(undefined);
      setFeedback(undefined);
    },
    onRemove: (phone) => void onRemove(phone),
    onRetry: () => void refresh()
  };
}

/**
 * A phone number the signed-in account has claimed. It stays unverified until the account proves possession
 * with a text-message code, and only a verified number can sign in or back a second factor.
 */
export type AccountPhoneNumber = Readonly<{
  id: string;
  /** E.164, e.g. `+12025550143`. */
  number: string;
  isVerified: boolean;
  isPrimary: boolean;
}>;

export type AccountPhoneNumberRef = Readonly<{ id: string; number: string }>;

/**
 * Host-owned data access. The block never builds requests or holds credentials: bind each call to the identity
 * the host rendered it for, and throw on failure. Throw `AccountPhoneNumbersUnavailableError` when the backend
 * has no phone support at all, and an error with a `code` (an `AccountPhoneNumbersError`, or a GraphQL error's
 * `extensions.code`) to pick a message from `messages.errors`.
 */
export type AccountPhoneNumbersAdapter = Readonly<{
  list: () => Promise<readonly AccountPhoneNumber[]>;
  /** Claims a number, already normalized to E.164. The block texts it a code right after. */
  add: (input: Readonly<{ number: string }>) => Promise<AccountPhoneNumber>;
  /** Texts a code to a claimed number; resolve `false` when nothing was sent because it is already verified. */
  sendCode: (input: AccountPhoneNumberRef) => Promise<boolean>;
  /** Resolves `true` when the code matched and the number is now verified, `false` for a wrong or expired code. */
  verify: (input: AccountPhoneNumberRef & Readonly<{ code: string }>) => Promise<boolean>;
  remove: (input: AccountPhoneNumberRef) => Promise<void>;
}>;

export type AccountPhoneNumbersAction = 'load' | 'add' | 'send' | 'verify' | 'remove';

/** Where a message belongs: the whole card, the add form, or one number's row. */
export type AccountPhoneNumbersScope = Readonly<
  { scope: 'card' } | { scope: 'add' } | { scope: 'phone'; phoneId: string }
>;

/** One visible error and/or announced notice, shown in the place its scope names. */
export type AccountPhoneNumbersFeedback = AccountPhoneNumbersScope & Readonly<{ error?: string; notice?: string }>;

/** The request in flight: claiming a new number, or an action on one row. */
export type AccountPhoneNumbersBusy = Readonly<
  { scope: 'add' } | { scope: 'phone'; phoneId: string; action: 'send' | 'verify' | 'remove' }
>;

/** The open code field and what has been typed into it. */
export type AccountPhoneNumbersCodeEntry = Readonly<{ phoneId: string; code: string }>;

/** Carries a backend error code so the block can show the matching message from `messages.errors`. */
export class AccountPhoneNumbersError extends Error {
  readonly code: string;

  constructor(code: string, message?: string) {
    super(message ?? code);
    this.name = 'AccountPhoneNumbersError';
    this.code = code;
  }
}

/** The authentication service has no phone-number support; the block shows a quiet notice instead of the list. */
export class AccountPhoneNumbersUnavailableError extends Error {
  constructor(message = 'Phone numbers are not available on this authentication service.') {
    super(message);
    this.name = 'AccountPhoneNumbersUnavailableError';
  }
}

